import {navIcon} from './icons.js';
import {themeCover,usesDefaultCover} from './theme-covers.js';
import {escapeHTML as e,plain,imageURL} from './store.js';
const quickOptions=[['notes','Notas & documentos'],['characters','Personagens'],['plot','Trama & plot'],['maps','Atlas de mapas'],['globe','Globo 3D'],['bestiary','Bestiário'],['calendar','Calendário'],['connections','Conexões'],['timeline','Linha do tempo'],['scenes','Cenas']];
export function dashboard(w,o,counts,btn,settings,state){
 const all=[...w.notes,...w.folderNotes],recent=[...all].sort((a,b)=>String(b.updated).localeCompare(String(a.updated))).slice(0,5),chosen=all.find(n=>n.id===w.goalDocument)||recent[0],words=chosen?plain(chosen.body).split(/\s+/).filter(Boolean).length:0,goal=Math.max(1,Number(w.writingGoal)||1500),pct=Math.min(100,Math.round(words/goal*100)),quick=w.overview.quickTabs||['notes','characters','maps','scenes'],welcomeMap=themeCover(w.overview,w.palette);
 const docButton=(doc,cls='')=>`<button class="${cls}" data-dashboard-document="${e(doc.id)}"><span>${navIcon('notes')}</span><span><strong>${e(doc.emoji||'')} ${e(doc.title)}</strong><small>${doc.folder?'Documento de pasta':'Documento'} · ${e(w.name)}</small></span><span class="quick-open">${navIcon('arrowUpRight')}</span></button>`;
 return `<div class="page overview-page atelier-home"><section class="atelier-welcome"><img class="atelier-welcome-map" data-default-cover="${usesDefaultCover(w.overview)}" src="${e(welcomeMap)}" alt="Mapa do universo"><div class="cover-controls home-cover-controls"><button type="button" id="changeCover">▧ Trocar capa</button><button type="button" id="resetCover" title="Restaurar capa padrão">Capa padrão</button><input type="file" id="overviewCoverFile" accept="image/*" hidden></div><div class="page-heading"><div><span class="eyebrow">ATELIÊ DE WORLDBUILDING</span><h1>Seu universo ganha forma</h1><p>Registre ideias, conecte lugares e avance na história.</p></div></div></section><section class="home-create-row"><p>Que parte do seu mundo vamos desenvolver?</p><button class="button home-new-button" data-action="create">＋ Novo</button></section><div class="home-dashboard-grid"><div class="home-primary-column">${o.shortcuts?`<section class="atelier-quick"><div class="section-heading"><div><span class="eyebrow">CONTINUE POR AQUI</span><h2>Acesso rápido</h2></div><details class="quick-customize"><summary aria-label="Editar acesso rápido" title="Editar acesso rápido">${navIcon('settings')}</summary><div class="quick-customize-menu"><strong>Escolha seus atalhos</strong>${quickOptions.map(([key,label])=>`<label>${label}<input type="checkbox" data-quick-toggle="${key}" ${quick.includes(key)?'checked':''}></label>`).join('')}</div></details></div><div class="atelier-quick-grid">${quick.map(key=>{const option=quickOptions.find(item=>item[0]===key);if(!option)return '';if(key==='notes')return recent[0]?docButton(recent[0],'atelier-quick-item'):viewButton(key,'▤','Notas & documentos','Suas páginas');if(key==='characters')return viewButton(key,'♙','Personagens',`${w.characters.length} fichas`);if(key==='maps')return viewButton(key,'⌖',w.maps[0]?.name||'Atlas de mapas',`${w.maps.length} mapas`);if(key==='scenes')return viewButton(key,'✎','Cenas',`${w.narrative?.scenes?.length||0} cenas`);return viewButton(key,'✧',option[1],'Abrir espaço');}).join('')||'<p class="help">Escolha ferramentas no botão de edição.</p>'}</div></section>`:''}${o.inspiration?`<section class="atelier-panel atelier-ideas"><div class="section-heading"><div><span class="eyebrow">ANOTE SEM PERDER O FIO</span><h2>Ideias e inspirações</h2></div></div><div id="ideaScratch" contenteditable="plaintext-only" role="textbox" aria-label="Ideias e inspirações" data-placeholder="Capture uma ideia para depois…">${e(o.scratch||'')}</div><blockquote><span data-overview-field="quote">${e(o.quote)}</span><small data-overview-field="author">${e(o.author)}</small></blockquote></section>`:''}</div><aside class="home-side-column"><section class="atelier-panel writing-goals"><div class="section-heading"><div><span class="eyebrow">SEU RITMO, SUA HISTÓRIA</span><h2>Meta de escrita</h2></div></div><div class="writing-goal-content"><div class="goal-ring" style="--progress:${pct}%"><strong id="goalPercent">${pct}%</strong></div><div><label class="field"><span>Documento</span><select id="goalDocument">${all.length?all.map(n=>`<option value="${e(n.id)}" ${chosen?.id===n.id?'selected':''}>${e(n.title)}</option>`).join(''):'<option>Nenhum documento</option>'}</select></label><p><strong id="goalWords">${words}</strong> palavras · objetivo ${goal}</p><progress id="goalProgress" value="${words}" max="${goal}"></progress></div></div><label class="goal-input">Meta de palavras <input id="writingGoal" type="number" min="1" max="1000000" value="${goal}" aria-label="Meta de palavras"></label></section>${o.recent?`<section class="atelier-panel recent-documents"><div class="section-heading"><div><span class="eyebrow">RETOME DE ONDE PAROU</span><h2>Últimos documentos</h2></div><button data-dashboard-view="notes" class="text-link">Ver todos ↗</button></div><div class="atelier-activity">${recent.map(n=>docButton(n)).join('')||'<p class="help">Suas próximas páginas aparecerão aqui.</p>'}</div></section>`:''}</aside></div></div>`;
}
function viewButton(key,icon,title,detail){return `<button class="atelier-quick-item" data-dashboard-view="${e(key)}"><span>${navIcon(key)}</span><span><strong>${e(title)}</strong><small>${e(detail)}</small></span><span class="quick-open">${navIcon('arrowUpRight')}</span></button>`}
export function mountDashboard(main,w,{save,rerender,openDocument,navigate}){
 const abort=new AbortController(),opts={signal:abort.signal};main.querySelectorAll('[data-dashboard-document]').forEach(b=>b.addEventListener('click',()=>openDocument(b.dataset.dashboardDocument),opts));main.querySelectorAll('[data-dashboard-view]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.dashboardView),opts));const scratch=main.querySelector('#ideaScratch');scratch?.addEventListener('input',()=>{w.overview.scratch=scratch.innerText.slice(0,10000);save();},opts);main.querySelectorAll('[data-quick-toggle]').forEach(input=>input.addEventListener('change',()=>{const selected=new Set(w.overview.quickTabs||['notes','characters','maps','scenes']);input.checked?selected.add(input.dataset.quickToggle):selected.delete(input.dataset.quickToggle);w.overview.quickTabs=[...selected];save();rerender();},opts));main.querySelector('#goalDocument')?.addEventListener('change',ev=>{w.goalDocument=ev.target.value;save();rerender();},opts);main.querySelector('#writingGoal')?.addEventListener('input',ev=>{const value=Number(ev.target.value);if(!Number.isInteger(value)||value<1||value>1000000)return;w.writingGoal=value;save();const words=Number(main.querySelector('#goalWords').textContent),pct=Math.min(100,Math.round(words/value*100));main.querySelector('#goalPercent').textContent=pct+'%';main.querySelector('.goal-ring').style.setProperty('--progress',pct+'%');main.querySelector('#goalProgress').max=value;},opts);return ()=>abort.abort();
}
